#include <iostream>

int main() {
    unsigned int positiveOnly = 4000000000;
    short int smallNumber = 32000;
    long int bigNumber = 2000000000L;
    long long int hugeNumber = 9000000000000LL;

    std::cout << "unsigned int: " << positiveOnly << std::endl;
    std::cout << "short int: " << smallNumber << std::endl;
    std::cout << "long int: " << bigNumber << std::endl;
    std::cout << "long long: " << hugeNumber << std::endl;

    std::cout << "Size of short: " << sizeof(short) << " bytes" << std::endl;
    std::cout << "Size of long long: " << sizeof(long long) << " bytes" << std::endl;

    return 0;
}

#include <iostream>

int main() {
    auto count = 10;        // Compiler infers int
    auto price = 19.99;     // Compiler infers double
    auto letter = 'A';      // Compiler infers char

    std::cout << "Count: " << count << " (type inferred)" << std::endl;
    std::cout << "Price: " << price << " (type inferred)" << std::endl;

    return 0;
}

#include <iostream>

int main() {
    int a = 17, b = 5;

    std::cout << "Addition: " << a + b << std::endl;
    std::cout << "Subtraction: " << a - b << std::endl;
    std::cout << "Multiplication: " << a * b << std::endl;
    std::cout << "Division (int): " << a / b << std::endl;  // Integer division!
    std::cout << "Division (float): " << (float)a / b << std::endl;
    std::cout << "Modulus: " << a % b << std::endl;

    return 0;
}

#include <iostream>

int main() {
    int x = 10, y = 20;

    std::cout << (x == y) << std::endl;  // 0 (false)
    std::cout << (x != y) << std::endl;  // 1 (true)
    std::cout << (x < y) << std::endl;   // 1 (true)
    std::cout << (x >= 10) << std::endl; // 1 (true)

    return 0;
}

#include <iostream>

int main() {
    int age = 25;
    bool hasID = true;

    std::cout << (age >= 18 && hasID) << std::endl;  // 1 (true)
    std::cout << (age < 18 || hasID) << std::endl;   // 1 (true)
    std::cout << (!hasID) << std::endl;              // 0 (false)

    return 0;
}

#include <iostream>

int main() {
    int a = 5, b = 5;

    std::cout << "Pre-increment: " << ++a << std::endl;  // 6 (incremented first)
    std::cout << "Post-increment: " << b++ << std::endl; // 5 (used first, then becomes 6)
    std::cout << "b is now: " << b << std::endl;         // 6

    return 0;
}
